// === Tab: mySketch.js ===
// p5.js Port (top -> topIdx)

let m = 25;
let n = 3000;

let b = new Array(m); // boolean[]
let x = Array.from({ length: m }, () => new Array(n).fill(0)); // float[m][n]
let y = Array.from({ length: m }, () => new Array(n).fill(0)); // float[m][n]
let l = new Array(m).fill(0);
let sw = new Array(m).fill(0);
let d = new Array(m).fill(0);
let ds = new Array(m).fill(0);
let da = new Array(m).fill(0);
let topIdx = new Array(m).fill(0); // int[] (NICHT "top")

let s = new Array(m).fill(0);
let sb = new Array(m).fill(0);

let sc = new Array(m).fill(0);

function setup() {
  createCanvas(800, 800);
  background(220);

  for (let i = 0; i < m; i++) {
    b[i] = (random(1) > 0.5);

    l[i] = int(random(1, 6)) * 20;
    d[i] = map(l[i], 10, 100, 5, 10);
    da[i] = d[i];
    ds[i] = map(l[i], 10, 100, 1.15, 0.15);
    x[i][0] = random(l[i] + 5, width - l[i] - 5);
    y[i][0] = height;
    sw[i] = random(0.25, 4.0);
    topIdx[i] = 1;
    s[i] = 0.0;
    sb[i] = int(l[i]);
    sc[i] = 0;
  }

  // Vorlauf / Aufbau (wie Processing-setup)
  for (let i = 0; i < m; i++) {
    for (let k = 0; k < 200; k++) {
      if (y[i][topIdx[i] - 1] > 0.85 * height) {
        if (b[i] === true) {
          if (x[i][topIdx[i] - 1] < l[i] + 5) {
            x[i][topIdx[i]] = x[i][topIdx[i] - 1] + l[i];
            y[i][topIdx[i]] = y[i][topIdx[i] - 1];
          } else if (x[i][topIdx[i] - 1] > (width - l[i] - 5)) {
            x[i][topIdx[i]] = x[i][topIdx[i] - 1] - l[i];
            y[i][topIdx[i]] = y[i][topIdx[i] - 1];
          } else {
            if (random(1) > 0.5) {
              x[i][topIdx[i]] = x[i][topIdx[i] - 1] + l[i];
              y[i][topIdx[i]] = y[i][topIdx[i] - 1];
            } else {
              x[i][topIdx[i]] = x[i][topIdx[i] - 1] - l[i];
              y[i][topIdx[i]] = y[i][topIdx[i] - 1];
            }
          }
          b[i] = !b[i];
        } else {
          x[i][topIdx[i]] = x[i][topIdx[i] - 1];
          y[i][topIdx[i]] = y[i][topIdx[i] - 1] - l[i];
          b[i] = !b[i];
        }

        topIdx[i]++;
        if (topIdx[i] === n - 1) topIdx[i] = 0;
      }
    }
  }
}

function draw() {
  background(220);

  // Zeichnen
  for (let j = 0; j < m; j++) {
    let ad = map(l[j], 10, 50, 0.85, 1.15);
    strokeWeight(sw[j]);
    stroke(10 + 5 * j);

    for (let i = 0; i < topIdx[j]; i++) {
      if (((sc[j] + i) % topIdx[j]) !== (topIdx[j] - 1)) {
        line(
          x[j][(sc[j] + i)],
          y[j][(sc[j] + i)] + s[j],
          x[j][(sc[j] + i + 1)],
          y[j][(sc[j] + i + 1)] + s[j]
        );

        ellipse(x[j][(sc[j] + i)], y[j][(sc[j] + i)] + s[j], 5, 5);
        ellipse(x[j][(sc[j] + i + 1)], y[j][(sc[j] + i + 1)] + s[j], 5, 5);
      }
    }

    s[j] += ad;
    if (s[j] > 10000) s[j] = 0;
  }

  // Wachstum / Update
  for (let i = 0; i < m; i++) {
    if (d[i] <= 0) {
      d[i] = da[i];

      if (b[i] === true) {
        if (x[i][topIdx[i] - 1] < l[i]) {
          x[i][topIdx[i]] = x[i][topIdx[i] - 1] + l[i];
          y[i][topIdx[i]] = y[i][topIdx[i] - 1];
        } else if (x[i][topIdx[i] - 1] > (width - l[i])) {
          x[i][topIdx[i]] = x[i][topIdx[i] - 1] - l[i];
          y[i][topIdx[i]] = y[i][topIdx[i] - 1];
        } else {
          if (random(1) > 0.5) {
            x[i][topIdx[i]] = x[i][topIdx[i] - 1] + l[i];
            y[i][topIdx[i]] = y[i][topIdx[i] - 1];
          } else {
            x[i][topIdx[i]] = x[i][topIdx[i] - 1] - l[i];
            y[i][topIdx[i]] = y[i][topIdx[i] - 1];
          }
        }
        b[i] = !b[i];
      } else {
        x[i][topIdx[i]] = x[i][topIdx[i] - 1];
        y[i][topIdx[i]] = y[i][topIdx[i] - 1] - l[i] + 1;
        b[i] = !b[i];
      }

      topIdx[i]++;
      if (topIdx[i] === n - 1) topIdx[i] = 0;
    } else {
      d[i] -= ds[i];
    }
  }
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
